using System; using System.Text; using UnityEngine; using UnityEditor; using UnityEditor.SceneManagement;
public static class VerifySwitchSupport {
public static string Run() {
if(EditorUtility.scriptCompilationFailed) throw new Exception("Compilation failed.");
var b=new StringBuilder();
foreach(var sw in UnityEngine.Object.FindObjectsByType<WeightSwitch>(FindObjectsInactive.Include)) Verify(sw,b);
foreach(var path in new[]{"Assets/Scenes/Stage1.unity","Assets/Scenes/CompletScene.unity"}) {
var scene=EditorSceneManager.OpenPreviewScene(path);
try { foreach(var root in scene.GetRootGameObjects()) foreach(var sw in root.GetComponentsInChildren<WeightSwitch>(true)) Verify(sw,b); }
finally { EditorSceneManager.ClosePreviewScene(scene); } }
b.AppendLine("compileFailed="+EditorUtility.scriptCompilationFailed+" playing="+EditorApplication.isPlaying);
return b.ToString(); }
static void Verify(WeightSwitch sw,StringBuilder b) {
var baseCollider=sw.transform.Find("Visual").GetComponent<BoxCollider2D>();
var cap=sw.transform.Find("Visual/PressureCap").GetComponent<BoxCollider2D>();
foreach(var c in new[]{baseCollider,cap}) if(c==null||c.isTrigger||c.includeLayers.value!=LayerMask.GetMask("player")||c.excludeLayers.value!=~LayerMask.GetMask("player")) throw new Exception("Invalid Player support: "+sw.name);
if(!sw.GetComponent<Collider2D>().isTrigger) throw new Exception("Morning Star detector lost trigger.");
b.AppendLine(sw.gameObject.scene.path+": inherited Player-only base and cap; Morning Star trigger retained.");
} }
